import math

def is_perfect_square(x):
    return math.isqrt(x) ** 2 == x

def find_permutation(n):
    def backtrack(path, used):
        if len(path) == n:
            return path
        for i in range(n):
            if not used[i]:
                if is_perfect_square(i + path[-1]):
                    used[i] = True
                    result = backtrack(path + [i], used)
                    if result:
                        return result
                    used[i] = False
        return None

    for start in range(n):
        used = [False] * n
        used[start] = True
        result = backtrack([start], used)
        if result:
            return result
    return [-1]

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        permutation = find_permutation(n)
        if permutation == [-1]:
            print(-1)
        else:
            print(' '.join(map(str, permutation)))

if __name__ == "__main__":
    main()
